"""Implement Queue using Stacks — amortised O(1) with two stacks.

Pushes land on `_in`; pops drain `_in` into `_out` only when `_out` is empty, so
every element moves at most twice.

Time: O(1) amortised   Space: O(n)
"""


class MyQueue:
    def __init__(self):
        self._in = []
        self._out = []

    def _shift(self) -> None:
        if not self._out:
            while self._in:
                self._out.append(self._in.pop())

    def push(self, x: int) -> None:
        self._in.append(x)

    def pop(self) -> int:
        self._shift()
        return self._out.pop()

    def peek(self) -> int:
        self._shift()
        return self._out[-1]

    def empty(self) -> bool:
        return not self._in and not self._out
